 value="{{ old('dpi',$template->dpi) }}" class="mt-2 w-full rounded-xl border p-3"></label><label>حداکثر حجم تصویر (KB)<input name="max_image_size_kb" type="number" min="100" required value="{{ old('max_image_size_kb',$template->max_image_size_kb) }}" class="mt-2 w-full rounded-xl border p-3"></label><fieldset class="md:col-span-2"><legend class="font-bold">فرمت‌های مجاز</legend><div class="mt-2 flex gap-4">@foreach(['jpg','jpeg','png','webp'] as $format)<label class="flex items-center gap-2"><input type="checkbox" name="allowed_formats[]" value="{{ $format }}" @checked(in_array($format,old('allowed_formats',$template->allowed_formats ?? ['jpg','jpeg','png','webp'])))>{{ strtoupper($format) }}</label>@endforeach</div></fieldset><label class="md:col-span-2">تصویر راهنمای قالب (اختیاری، حداکثر ۱۰MB)<input type="file" name="template_image" accept="image/jpeg,image/png,image/webp" class="mt-2 w-full rounded-xl border p-3"></label>@if($template->template_image_path)<div><img class="max-h-48 rounded-xl" src="{{ route('admin.print-templates.image',$template) }}" alt="تصویر قالب"></div>@endif<label class="flex items-center gap-2"><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$template->exists ? $template->is_active : true))> فعال باشد</label></div><button class="mt-6 rounded-xl bg-violet-700 px-6 py-3 font-bold text-white">ذخیره قالب</button></form></main></body></html>
